import re, collections
from pathlib import Path
root=Path('work/lab1/project')
checks={
 'email_address':r'(?i)(?<![\w.-])[a-z0-9_+.-]+@[a-z0-9.-]+\.[a-z]{2,}(?![\w.-])',
 'smtp_trace_header':r'(?im)^(?:Received|X-Originating-IP|Return-Path|Reply-To|Delivered-To|Message-ID)\s*:',
 'private_ipv4':r'(?<![\d.])(?:10\.\d{1,3}\.\d{1,3}\.\d{1,3}|192\.168\.\d{1,3}\.\d{1,3}|172\.(?:1[6-9]|2[0-9]|3[01])\.\d{1,3}\.\d{1,3})(?![\d.])',
 'auth_query':r'(?i)[?&](?:access_token|auth|token|key|secret|password|signature|sig)=[a-z0-9._%+-]{8,}',
}
for group, files in [('raw email',list((root/'data/raw').glob('*.eml'))),('exercise.csv',[root/'data/exercise.csv']),('demo.csv',[root/'data/demo.csv']),('source/tests',[root/'describe_data.py',root/'tests/test_report.py',root/'tests/fixtures/messages.csv'])]:
    occurrences=collections.Counter(); files_hit=collections.Counter()
    for path in files:
        text=path.read_text(encoding='utf-8',errors='replace')
        for name, rx in checks.items():
            c=len(re.findall(rx,text))
            if c:
                occurrences[name]+=c; files_hit[name]+=1
    print(group,len(files),'matches',dict(occurrences),'files',dict(files_hit))
